import React from "react";
import { LOGO_FRACTION } from "./wolffShared";

// ---------------------------------------------------------------------------
// wolffLogos — the four named rivals' crests for cut 5 `MostSponsorship` of the
// Toto Wolff "Mercedes F1 financials" clip (Cheeky Pint S4E01), as monochrome
// knock-outs for `LogoTile` in wolffShared.tsx.
//
// The crest's DARK parts are knocked out of the white tile (the paper shows
// through, like a rubber-stamp print); its LIGHT parts stay tile-white; any
// background rect is dropped; the silhouette is kept.
//
// SOURCE: the four crest SVGs the director downloaded and checked after the
// user's approval (Oct 2 2026), read from the session's scratchpad/logos/ and
// converted here once by scratchpad/crestconv.py (per-element rules, below in
// each `source`). The path data is inlined: no <image>, no staticFile. Each
// crest is made recognisable rather than complete: its silhouette and the one
// or two features a fan knows it by (Real Madrid: the crown over the ring;
// Manchester United: the shield and the devil; Lakers: the wordmark over the
// ball; Cowboys: the star with its outline ring). `fraction` balances each
// mark's weight against the Mercedes ring (0.80 of its tile). A crest missing
// here falls back to its placeholder sport tile in MostSponsorship.
// ---------------------------------------------------------------------------

// Cut 5's four named rivals, and cut 4's two named US teams beside LAKERS and
// COWBOYS (builder B uses all four the same way: CRESTS[id] + crestFigure).
export type CrestId = "LAKERS" | "MANUTD" | "REALMADRID" | "COWBOYS" | "WARRIORS" | "KNICKS";

export type Crest = {
  /** the source SVG's viewBox, "minX minY width height" */
  viewBox: string;
  /** the crest drawn 1-bit in its own painting order, in viewBox units: every
   *  dark paint is fill/stroke "#000" (knocked out), every light paint "#fff"
   *  (tile-white), so a light shape over a dark one restores the tile exactly
   *  as the crest layers them. Rendered as LogoTile's `figure`. */
  markup: string;
  /** how much of the tile the crest fills (LogoTile's fraction; default LOGO_FRACTION) */
  fraction?: number;
  /** where the data came from, and the dark/light split used */
  source: string;
};

