/** A crest as LogoTile's `figure` (wolffShared): its 1-bit markup fitted and
 *  centred in `crest.fraction` of a tile of `size` world px, exactly the way
 *  LogoTile fits its own `paths`. Usage:
 *    <LogoTile x={x} y={GROUND_Y} k={k} size={TILE} opacity={op}
 *              figure={crestFigure(CRESTS.WARRIORS!, TILE)} /> */
export const crestFigure = (crest: Crest, size: number): React.ReactElement => {
  const [vx, vy, vw, vh] = crest.viewBox.trim().split(/[\s,]+/).map(Number);
  const sc = (size * (crest.fraction ?? LOGO_FRACTION)) / Math.max(vw, vh);
  const ox = (size - vw * sc) / 2 - vx * sc;
  const oy = (size - vh * sc) / 2 - vy * sc;
  return React.createElement("g", {
    transform: `translate(${ox.toFixed(3)} ${oy.toFixed(3)}) scale(${sc.toFixed(5)})`,
    dangerouslySetInnerHTML: { __html: crest.markup },
  });
};
